import { memo } from "react";
import { CardDescription, CardHeader, CardTitle } from "./card";
import { ShaderFrameCard, type ShaderFrameCardProps } from "./shader-frame-card.shared";
import { RayFieldBackground } from "../shader/ray-field-background";

type LightRayFrameCardProps = ShaderFrameCardProps & { speed?: number };

export const LightRayFrameCard = memo(function LightRayFrameCard({
  speed = 1,
  children = (
    <CardHeader>
      <CardTitle>Follow the light.</CardTitle>
      <CardDescription>
        A sweeping light ray frames a quiet space for your next idea.
      </CardDescription>
    </CardHeader>
  ),
  ...props
}: LightRayFrameCardProps = {}) {
  return (
    <ShaderFrameCard
      {...props}
      slot="light-ray-frame-card"
      background={
        <RayFieldBackground
          speed={speed}
          interactive={false}
          className="absolute inset-0 h-full min-h-0! w-full border-0"
        />
      }
    >
      {children}
    </ShaderFrameCard>
  );
});

"use client";

import { memo, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, type HTMLMotionProps } from "motion/react";
import { cn } from "cn";
import { Card } from "./card";

export type ShaderFrameCardProps = Omit<HTMLMotionProps<"div">, "color" | "children"> & {
  frameWidth?: number;
  contentClassName?: string;
  children?: ReactNode;
};

export const ShaderFrameCard = memo(function ShaderFrameCard({
  background,
  slot,
  frameWidth = 12,
  contentClassName,
  children,
  className,
  style,
  ...props
}: ShaderFrameCardProps & { background: ReactNode; slot: string }) {
  const reducedMotion = useReducedMotion();
  const inset = Number.isFinite(frameWidth) ? Math.max(0, frameWidth) : 12;
  return (
    <motion.div
      {...props}
      data-slot={slot}
      initial={reducedMotion ? false : { opacity: 0, y: 0 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={reducedMotion ? undefined : { y: -3 }}
      transition={
        reducedMotion
          ? { duration: 0 }
          : { duration: 0.2, ease: "easeOut", y: { type: "spring", stiffness: 220, damping: 26 } }
      }
      className={cn(
        "relative isolate w-full min-w-0 max-w-md overflow-hidden rounded-xl bg-card",
        className,
      )}
      style={{ padding: inset, ...style }}
    >
      <motion.div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 rounded-[inherit]"
        initial={reducedMotion ? false : { opacity: 0, clipPath: "inset(0 100% 0 0)" }}
        animate={{ opacity: 1, clipPath: "inset(0 0% 0 0)" }}
        transition={
          reducedMotion ? { duration: 0 } : { delay: 0.2, duration: 0.55, ease: "easeInOut" }
        }
        style={{
          padding: inset,
          maskImage: "linear-gradient(#000 0 0), linear-gradient(#000 0 0)",
          maskClip: "content-box, border-box",
          maskComposite: "exclude",
          WebkitMaskComposite: "xor",
        }}
      >
        {background}
      </motion.div>
      <motion.div
        className="relative min-w-0"
        initial={reducedMotion ? false : { opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        transition={
          reducedMotion ? { duration: 0 } : { delay: 0.8, duration: 0.3, ease: "easeOut" }
        }
      >
        <Card
          className={cn(
            "relative max-w-none bg-card text-card-foreground ring-0",
            contentClassName,
          )}
        >
          {children}
        </Card>
      </motion.div>
    </motion.div>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };

"use client";

import { memo, type ComponentProps } from "react";
import { useReducedMotion, useSpring } from "motion/react";
import { cn } from "cn";
import { Canvas } from "./canvas";
import shader from "./wordmark-light-ray.wgsl";

export type RayFieldBackgroundProps = ComponentProps<"div"> & {
  speed?: number;
  intensity?: number;
  interactive?: boolean;
};

export const RayFieldBackground = memo(function RayFieldBackground({
  className,
  children,
  speed = 1,
  intensity = 1,
  interactive = true,
  onPointerMove,
  onPointerLeave,
  ...props
}: RayFieldBackgroundProps = {}) {
  const reducedMotion = useReducedMotion();
  const x = useSpring(0.5, { stiffness: 180, damping: 24 });
  const y = useSpring(0.5, { stiffness: 180, damping: 24 });
  const hover = useSpring(0, { stiffness: 220, damping: 26 });
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 1;
  const brightness = Number.isFinite(intensity) ? Math.max(0, Math.min(2, intensity)) : 1;

  return (
    <div
      {...props}
      data-slot="ray-field-background"
      className={cn("relative isolate min-h-96 overflow-hidden bg-background", className)}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (!interactive || reducedMotion || event.pointerType === "touch") return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (!bounds.width || !bounds.height) return;
        x.set(Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width)));
        y.set(Math.max(0, Math.min(1, (event.clientY - bounds.top) / bounds.height)));
        hover.set(1);
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        x.set(0.5);
        y.set(0.5);
        hover.set(0);
      }}
    >
      <Canvas
        aria-label="Animated blue light ray field"
        role="img"
        shader={shader}
        label="ray-field-background"
        lightFallback="linear-gradient(100deg, #f0f7fc 30%, #164880 50%, #f0f7fc 65%)"
        fallback="radial-gradient(ellipse at 50% 50%, #1d5f9a 0%, transparent 28%), linear-gradient(110deg, #02070d, #071522 48%, #02070d)"
        className="absolute inset-0 -z-10 h-full min-h-0 border-0 bg-transparent"
        animated={rate > 0}
        fps={30}
        uniforms={(time, size) => ({
          cfg: {
            ray: [
              x.get() * size[0],
              y.get() * size[1],
              time * rate,
              (interactive && !reducedMotion ? hover.get() : 0) * brightness,
            ],
          },
        })}
      />
      {children}
    </div>
  );
});

"use client";

import { memo, useEffect, useRef, type ReactNode, type ComponentProps } from "react";
import { useReducedMotion } from "motion/react";
import { createShaderRenderer, type PostProcessOptions } from "./shader-renderer.shared";
import { cn } from "cn";

type RendererOptions = Parameters<typeof createShaderRenderer>[2];
export interface CanvasProps extends ComponentProps<"div"> {
  shader: Parameters<typeof createShaderRenderer>[1];
  label?: string;
  fallback: string;
  lightFallback: string;
  fallbackContent?: ReactNode;
  uniforms: RendererOptions["uniforms"];
  animated?: boolean;
  fps?: number;
  dpr?: number | [number, number];
  postProcess?: PostProcessOptions;
}

/** Shared rendering only; consumers own uniforms and pointer behavior. */
export const Canvas = memo(function Canvas({
  shader,
  label = "shader-canvas",
  fallback,
  lightFallback,
  fallbackContent,
  uniforms,
  animated = true,
  fps = 30,
  dpr = 1,
  postProcess,
  className,
  children,
  ...props
}: CanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const latestUniforms = useRef(uniforms);
  const rendererRef = useRef<ReturnType<typeof createShaderRenderer> | null>(null);
  const reducedMotion = useReducedMotion();
  const minDpr = typeof dpr === "number" ? dpr : dpr[0];
  const maxDpr = typeof dpr === "number" ? dpr : dpr[1];
  useEffect(() => {
    latestUniforms.current = uniforms;
    rendererRef.current?.render();
  }, [uniforms]);
  useEffect(() => {
    if (!canvasRef.current) return;
    const renderer = createShaderRenderer(canvasRef.current, shader, {
      label,
      uniforms: (time, size) => latestUniforms.current(time, size),
      animated: animated && !reducedMotion,
      fps,
      surface: { dpr: minDpr === maxDpr ? minDpr : [minDpr, maxDpr] },
      postProcess,
    });
    rendererRef.current = renderer;
    return () => {
      renderer.dispose();
      rendererRef.current = null;
    };
  }, [shader, label, animated, reducedMotion, fps, minDpr, maxDpr, postProcess]);
  return (
    <div
      {...props}
      data-slot={label}
      className={cn(
        "hangry-background relative isolate min-h-96 overflow-hidden border border-border bg-background",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        <div className="absolute inset-0 dark:hidden" style={{ backgroundImage: lightFallback }} />
        <div className="absolute inset-0 hidden dark:block">
          <div className="absolute inset-0" style={{ backgroundImage: fallback }} />
          {fallbackContent}
        </div>
        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />
      </div>
      {children}
    </div>
  );
});

import { lightBlue, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  // Pointer in wordmark pixels, elapsed seconds, and hover state.
  ray: vec4f,
};

@group(0) @binding(0) var<uniform> cfg: Config;

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let pointer = cfg.ray.xy / vec2f(1337.0, 336.0);
  // Start inside the mark so reduced motion still shows a complete beam.
  let scan = fract(cfg.ray.z * 0.14 + 0.45) * 1.6 - 0.3;
  let beam_x = mix(scan, pointer.x, cfg.ray.w);
  let beam_y = mix(0.5, pointer.y, cfg.ray.w);
  let offset = uv.x - beam_x + (uv.y - beam_y) * 0.14;
  let core = exp(-pow(offset / 0.009, 2.0));
  let halo = exp(-pow(offset / 0.065, 2.0));
  // A broad, asymmetric wake makes the direction of the ray visible.
  let trail = exp(min(offset, 0.0) / 0.15) * (1.0 - smoothstep(-0.005, 0.025, offset));
  if (theme.mode.x > 0.5 && theme.mode.y > 0.5) {
    let ink = clamp(0.08 + trail * 0.28 + halo * 0.4 + core * 0.9, 0.0, 1.0);
    return vec4f(vec3f(1.0 - ink), 1.0);
  }
  if (theme.mode.x > 0.5) {
    let beam = clamp(trail * 0.35 + halo * 0.5 + core * 0.8, 0.0, 1.0);
    return vec4f(mix(lightPaper(), lightBlue(), beam), 1.0);
  }
  let color = vec3f(0.025, 0.045, 0.065)
    + vec3f(0.1, 0.45, 0.8) * trail * 0.65
    + vec3f(0.25, 0.7, 1.0) * halo * 0.65
    + vec3f(0.85, 0.95, 1.0) * core;
  return vec4f(color, 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
